from typing import List

def sort_numbers(numbers: str) -> str:
    number_words = ["zero", "one", "two", "three", "four", "five", "six", "seven", "eight", "nine"]
    number_dict = {word: index for index, word in enumerate(number_words)}

    # Split the input string into a list of words
    numbers_list = numbers.split()

    # Sort the list using the indices from the dictionary
    sorted_numbers = sorted(numbers_list, key=lambda x: number_dict[x])

    # Join the sorted list back into a space-delimited string
    return ' '.join(sorted_numbers)

